public class MultiplePiePlot_MultiplePiePlot_TriageGen1Test {

    @Test
    public void testConstructorWithDataset() {
        // Arrange
        CategoryDataset mockDataset = mock(CategoryDataset.class);

        // Act
        MultiplePiePlot plot = new MultiplePiePlot(mockDataset);

        // Assert
        // Check dataset assignment
        assertEquals("Dataset should be assigned correctly", mockDataset, plot.getDataset());

        // Check PieChart initialization and properties
        JFreeChart chart = plot.getPieChart();
        assertNotNull("PieChart should not be null", chart);
        assertNull("Background paint should be null", chart.getBackgroundPaint());

        // Check title configuration
        TextTitle title = (TextTitle) chart.getTitle();
        assertNotNull("Title should be initialized", title);
        assertEquals("Series Title", title.getText());
        assertEquals(Font.SANS_SERIF, title.getFont().getFamily());
        assertEquals(Font.BOLD, title.getFont().getStyle());
        assertEquals(12, title.getFont().getSize());

        // Check default internal states set by constructor
        assertEquals("Data extract order should be BY_COLUMN", TableOrder.BY_COLUMN, plot.getDataExtractOrder());
        assertEquals("Aggregated items key should be 'Other'", "Other", plot.getAggregatedItemsKey());
        assertEquals("Aggregated items paint should be light gray", Color.lightGray, plot.getAggregatedItemsPaint());
    }

    @Test
    public void testDefaultConstructor() {
        // Act
        MultiplePiePlot plot = new MultiplePiePlot();

        // Assert
        assertNull("Dataset should be null for default constructor", plot.getDataset());
        assertNotNull("PieChart should still be initialized", plot.getPieChart());
    }

    @Test
    public void testSettersAndGetters() {
        // Arrange
        MultiplePiePlot plot = new MultiplePiePlot();
        CategoryDataset mockDataset = mock(CategoryDataset.class);
        JFreeChart mockChart = mock(JFreeChart.class);
        TableOrder newOrder = TableOrder.BY_ROW;
        double newLimit = 5.0;
        String newKey = "NewKey";
        Color newPaint = Color.RED;

        // Act & Assert
        plot.setDataset(mockDataset);
        assertEquals(mockDataset, plot.getDataset());

        plot.setPieChart(mockChart);
        assertEquals(mockChart, plot.getPieChart());

        plot.setDataExtractOrder(newOrder);
        assertEquals(newOrder, plot.getDataExtractOrder());

        plot.setLimit(newLimit);
        assertEquals(newLimit, plot.getLimit(), 0.0001);

        plot.setAggregatedItemsKey(newKey);
        assertEquals(newKey, plot.getAggregatedItemsKey());

        plot.setAggregatedItemsPaint(newPaint);
        assertEquals(newPaint, plot.getAggregatedItemsPaint());
    }

    @Test
    public void testEquals() {
        // Arrange
        MultiplePiePlot plot1 = new MultiplePiePlot();
        MultiplePiePlot plot2 = new MultiplePiePlot();

        // Act & Assert
        // Note: Implementation of equals is not provided in snippet, 
        // but we test the basic Object contract behavior
        assertNotEquals("Different instances should not be equal by default", plot1, plot2);
        assertEquals("An object should be equal to itself", plot1, plot1);
        assertNotEquals("Should not be equal to null", plot1, null);
        assertNotEquals("Should not be equal to different type", plot1, "String");
    }
}
